        try {
            Xrd81 user = userRepository.findByEmail(email)
                    .orElseThrow(() -> new Xkk16Exception(
                            "이메일 '" + email + "'에 해당하는 사용자를 찾을 수 없습니다."
                    ));

            log.info("주소 수정 시작: 사용자={}, 주소ID={}", email, updateDto.getAddressId());

            Xms98 address = addressRepository.findByIdAndUser(updateDto.getAddressId(), user)
